var a=`0928-scallion-pancakes`;var i=`world-0928`;var s=`CN`;var t=`east-asia`;var o=8;var l=69;var r={en:`Scallion Pancakes`,ua:`Млинці із зеленою цибулею`};var d={en:`Scallion Pancakes is a China dish made with all-purpose flour, green onion, black rice vinegar. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Млинці із зеленою цибулею, страва кухні країни Китай. Основні складники: пшеничне борошно універсальне, зелена цибуля, чорний рисовий оцет. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,420,`g`],[`water`,225,`ml`],[`table-salt`,5,`g`]]},{en:`Roll dough thin, brush with sesame oil, scatter scallions, coil tightly and flatten again for flaky layers.`,ua:`Тонко розкачайте тісто, змастіть кунжутною олією, посипте зеленою цибулею, туго скрутіть та знову розпластайте для шаруватості.`,t:[`layered-assembly`],m:12,i:[[`green-onion`,130,`g`],[`toasted-sesame-oil`,65,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 22 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 22 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:22,i:[[`canola-oil`,55,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`black-rice-vinegar`,45,`ml`]]}];var g={slug:a,id:i,country:`CN`,region:t,servings:8,minutes:69,title:r,text:d,steps:h};export{s as country,g as default,i as id,l as minutes,t as region,o as servings,a as slug,h as steps,d as text,r as title};